import{_ as i,o as e,c as n,ah as o}from"./chunks/framework.D4KxWb5R.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/administration/settings.md","filePath":"src/en/guide/administration/settings.md"}'),a={name:"en/guide/administration/settings.md"};function s(r,t,d,c,l,g){return e(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>M&#39;City&#39;s management settings are changed from the back-office, without edPage. CEO only. Each change applies immediately and is recorded in the <a href="./logs.html">audit log</a>, with its author, date, old and new value.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><strong>Administration → Configuration</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td>Invitation validity (days)</td><td>7</td><td>How long a temporary password works, fixed when sent.</td></tr><tr><td>Sign-out after inactivity (minutes)</td><td>30</td><td>Intranet and back-office sessions close after this time without activity.</td></tr><tr><td>Minimum password length</td><td>12</td><td>Applies to every new password; 8 at least.</td></tr><tr><td>Require two-factor authentication for everyone</td><td>No</td><td>Every account gets an e-mail code at sign-in, unless it uses an authenticator app or a passkey. It can also be required account by account.</td></tr><tr><td>Language of new accounts</td><td>English</td><td>Offered when an account is created.</td></tr><tr><td>Resynchronization attempts</td><td>5</td><td>How many times a product is sent to its back-office before it is declared desynchronized (1 to 20).</td></tr><tr><td>Activity window (days)</td><td>30</td><td>Rolling window of an &quot;active user&quot;, unless an indicator sets its own.</td></tr><tr><td>Indicator reporting</td><td>Sent by the product</td><td>The products&#39; default mode; each product can change it on its integration page.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">E-mail code</p><p>With e-mail two-factor authentication, signing in depends on e-mail delivery: if M&#39;City IQ&#39;s e-mails stop going out, those accounts can no longer sign in.</p></div><h2 id="indicator-definitions" tabindex="-1">Indicator definitions <a class="header-anchor" href="#indicator-definitions" aria-label="Permalink to &quot;Indicator definitions&quot;">​</a></h2><p><strong>Administration → Indicators</strong> lists the consolidated indicators and the products that report them. An indicator is added without development, as long as the product can supply it.</p><ol><li><strong>New indicator</strong> (or open an indicator).</li><li><strong>Key</strong>: the identifier the products use (lowercase, digits, <code>_</code>). It can&#39;t change after creation.</li><li><strong>Label</strong>, in English and French.</li><li><strong>Aggregation</strong>: distinct count, sum or ratio. Only a sum adds up across products.</li><li><strong>Window (days)</strong>: empty to use the configuration&#39;s activity window.</li><li><strong>Source products</strong>: only these products can report the indicator.</li><li><strong>Active</strong>: an inactive indicator is no longer accepted or shown; its values are kept.</li></ol><p>Tell the product&#39;s team: it must expose the indicator, through the API or at its polling endpoint (see <a href="./../integration/indicators.html">Indicators</a>).</p>',10)])])}const p=i(a,[["render",s]]);export{u as __pageData,p as default};
